, \"presence_penalty\": 0.5, \"query\": \"sys.query\", \"temperature\": 0.2, \"temperatureEnabled\": false, \"topPEnabled\": false, \"top_p\": 0.75}, \"label\": \"Categorize\", \"name\": \"Review categorize\"}, \"dragging\": false, \"id\": \"Categorize:RottenWallsObey\", \"measured\": {\"height\": 140, \"width\": 200}, \"position\": {\"x\": 374.0221988829014, \"y\": 37.350593375729275}, \"selected\": false, \"sourcePosition\": \"right\", \"targetPosition\": \"left\", \"type\": \"categorizeNode\"}, {\"data\": {\"form\": {\"frequencyPenaltyEnabled\": false, \"frequency_penalty\": 0.7, \"items\": [{\"description\": \"The negative review is about after-sales issues.\", \"examples\": [{\"value\": \"1. The product easily broke down.\\n2. I need to change a new one.\\n3. It is not the type I ordered.\"}], \"name\": \"After-sales issues\", \"uuid\": \"a1f3068c-85d8-4cfa-aa86-ef1f71d2edce\"}, {\"description\": \"The negative review is about transportation issue.\", \"examples\": [{\"value\": \"1. The transportation is delayed too much.\\n2. I can\'t find where is my order now.\"}], \"name\": \"Transportation issue\", \"uuid\": \"2fda442d-8580-440c-a947-0df607ca56fe\"}], \"llm_id\": \"deepseek-chat@DeepSeek\", \"maxTokensEnabled\": false, \"max_tokens\": 256, \"message_history_window_size\": 1, \"outputs\": {\"category_name\": {\"type\": \"string\"}}, \"parameter\": \"Precise\", \"presencePenaltyEnabled\": false, \"presence_penalty\": 0.4, \"query\": \"sys.query\", \"temperature\": 0, \"temperatureEnabled\": true, \"topPEnabled\": false, \"top_p\": 0.3}, \"label\": \"Categorize\", \"name\": \"Negative review categorize\"}, \"dragging\": false, \"id\": \"Categorize:FourTeamsFold\", \"measured\": {\"height\": 140, \"width\": 200}, \"position\": {\"x\": 706.0637059431883, \"y\": 244.46649585736282}, \"selected\": false, \"sourcePosition\": \"right\", \"targetPosition\": \"left\", \"type\": \"categorizeNode\"}, {\"data\": {\"form\": {\"cc_email\": \"\", \"content\": \"{begin@1}\"